                return (
                  <ListItem key={department?.id ?? 'unknown'} disablePadding sx={{ mb: 0.5 }}>
                    <ListItemButton
                      onClick={() => handleDepartmentClick(department?.id ?? '')}
                      sx={{
                        borderRadius: 2,
                        py: 1.5,
                        backgroundColor: isActive ? 'primary.main' : 'transparent',
                        color: isActive ? 'white' : 'grey.800',
